<template><section class="scr-card"><h3>{{ t('settings.safety') }}</h3><ToggleField :model-value="settings.allowMissingParts === true" :label="t('settings.allowMissing')" @update:model-value="value => update('allowMissingParts', value)" /><ToggleField :model-value="settings.protectCriticalParts === true" :label="t('settings.protectCritical')" @update:model-value="value => update('protectCriticalParts', value)" /><ToggleField :model-value="settings.extremeTuning === true" :label="t('settings.extremeTuning')" @update:model-value="value => update('extremeTuning', value)" /><ToggleField :model-value="settings.allowPartialResult === true" :label="t('settings.partialResult')" @update:model-value="value => update('allowPartialResult', value)" /></section></template>
<script setup>import { useStores } from "../../stores"; import ToggleField from "../common/ToggleField.vue"; const stores = useStores(); const settings = stores.settings.state; const { t } = stores.i18n; const update = (field, value) => stores.command.send("updateSettings", [{ [field]: value }])</script>
